package net.civeira.phylax.feature.identity.user.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.crypto.PasswordHasher;

class PasswordVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property password of user ")
  void test_password_v_o_builder() {
    PasswordHasher service = Mockito.mock(PasswordHasher.class);
    Mockito.when(service.hash("small")).thenReturn("$argon2id$example");
    Assertions.assertEquals("$argon2id$example",
        PasswordVO.fromPlain("small").getPasswordStored(service));
    Assertions.assertEquals("****", PasswordVO.fromPlain("small").toString());
  }
}
